import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const run = (root, ...args) => {
  try {
    return execFileSync('git', args, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe']
    }).trim();
  } catch {
    return null;
  }
};

const formatApiReport = dtsContent => {
  // Strip source mapping URL and trailing whitespace
  const cleaned = dtsContent.replace(/\/\/# sourceMappingURL=.*$/m, '').trim();

  return [
    '## API Report File for "@correxit/contracts"',
    '',
    '> Do not edit this file. It is a report generated by `scripts/check-contracts-api.mjs`.',
    '',
    '```ts',
    cleaned,
    '```',
    ''
  ].join('\n');
};

export const check = ({
  update = false,
  root = resolve(import.meta.dirname, '..'),
  base = process.env.CONTRACTS_BASE || null
} = {}) => {
  const pkgPath = resolve(root, 'packages/contracts/package.json');
  const dtsPath = resolve(root, 'packages/contracts/lib/index.d.ts');
  const apiPath = resolve(root, 'packages/contracts/contracts.api.md');
  if (!existsSync(dtsPath)) {
    throw new Error(
      'packages/contracts/lib/index.d.ts does not exist. Run `jlpm build:contracts` first.'
    );
  }

  const dts = readFileSync(dtsPath, 'utf8');
  const expected = formatApiReport(dts);

  if (update) {
    writeFileSync(apiPath, expected, 'utf8');
    console.log('Updated packages/contracts/contracts.api.md');
    return;
  }

  if (!existsSync(apiPath)) {
    throw new Error(
      'packages/contracts/contracts.api.md does not exist. Run with --update to generate it.'
    );
  }

  const current = readFileSync(apiPath, 'utf8');
  if (current !== expected) {
    throw new Error(
      'API report in packages/contracts/contracts.api.md is out of date.\n' +
        'Run `jlpm contracts:update` to update it.'
    );
  }

  const revision = base || run(root, 'merge-base', 'origin/main', 'HEAD');
  if (
    !revision ||
    !run(root, 'rev-parse', '--verify', `${revision}^{commit}`)
  ) {
    throw new Error(
      'Cannot resolve the contracts base revision; fetch origin/main or set CONTRACTS_BASE.'
    );
  }
  const previous = run(
    root,
    'show',
    `${revision}:packages/contracts/contracts.api.md`
  );
  if (previous !== null && previous !== expected.trim()) {
    const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
    const before = JSON.parse(
      run(root, 'show', `${revision}:packages/contracts/package.json`)
    );
    const versions = [pkg.version, before.version];
    if (
      versions.some(
        version => !/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.test(version)
      )
    )
      throw new Error(
        'Contracts versions must be stable major.minor.patch versions.'
      );
    const [current, previous] = versions.map(version =>
      version.split('.').map(Number)
    );
    const increase =
      current
        .map((part, index) => part - previous[index])
        .find(part => part !== 0) ?? 0;
    if (increase <= 0) {
      throw new Error(
        `Contracts API changed since ${revision}, but version ${pkg.version} was not increased.\n` +
          'Increase packages/contracts/package.json version when changing the public API.'
      );
    }
  }
  console.log('API report is up to date.');
};

if (
  process.argv[1] &&
  resolve(process.argv[1]) === resolve(import.meta.filename)
) {
  const update = process.argv.includes('--update');
  try {
    check({ update });
  } catch (error) {
    console.error(error.message);
    process.exit(1);
  }
}
